SELECT 'core-2026-09-v4','degree-comparison','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"degree-comparison","title":"Degree: too, enough, so, such and comparison modifiers","level":"B1","order":47,"summary":"Express degree, sufficiency and excess, and make comparisons more precise.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Too means more than wanted","Enough has two positions","So and such","Modify comparisons and adjective strength"],"rules":[{"title":"Too means more than wanted","explanation":"Too + adjective/adverb means an excessive degree for the situation, often followed by a to-infinitive explaining the consequence. It is not simply a stronger version of very. Very hot can be a neutral description; too hot means a limit is exceeded.","pattern":"The soup is **too hot to drink**.","commonMistakes":["Too delicious usually does not mean very delicious unless there is a real problematic excess in context."],"examples":["The instructions let us do the task. “They are **clear enough** to help us prepare the visitor guide.”","The instructions let us do the task. “They are **clear enough** to help us restore the old portrait.”"],"skill":"form"},{"title":"Enough has two positions","explanation":"Enough normally follows an adjective or adverb but precedes a noun. It means the required amount or degree has been reached. A following infinitive can explain the purpose.","pattern":"**clear enough** / **enough time**","commonMistakes":["Enough clear and time enough are not the neutral patterns practised here, though literary placements may differ."],"examples":["“We have **enough time** to prepare the visitor guide before lunch.”","“We have **enough time** to restore the old portrait before lunch.”"],"skill":"meaning"},{"title":"So and such","explanation":"So usually modifies an adjective or adverb. Such modifies a noun phrase, with a/an before a singular count noun. So also combines with much, many, little and few to express quantity.","pattern":"**so useful** / **such a useful guide** / **so many guides**","commonMistakes":["Such useful a guide puts the article in the wrong position for this ordinary pattern."],"examples":["“It is **such a** useful task to prepare the visitor guide.”","“It is **such a** useful task to restore the old portrait.”"],"skill":"contrast"},{"title":"Modify comparisons and adjective strength","explanation":"Much, far and a little can modify a comparative; very does not normally do so directly. Extreme adjectives often take absolutely rather than very. Ordinary adjectives can take very or quite. The acceptable combinations are partly lexical and depend on the adjective’s sense.","pattern":"**much easier** / **a little easier** / **absolutely exhausted**","commonMistakes":["Very easier is not the ordinary comparative pattern. Some adjectives have both gradable and non-gradable senses."],"examples":["Choose the degree modifier that fits: “It is **much** easier to prepare the visitor guide with help.”","Choose the degree modifier that fits: “It is **much** easier to restore the old portrait with help.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Express degree, sufficiency and excess, and make comparisons more precise.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Too means more than wanted","explanation":"Too + adjective/adverb means an excessive degree for the situation, often followed by a to-infinitive explaining the consequence. It is not simply a stronger version of very. Very hot can be a neutral description; too hot means a limit is exceeded.","pattern":"The soup is **too hot to drink**.","commonMistakes":["Too delicious usually does not mean very delicious unless there is a real problematic excess in context."],"examples":["The instructions let us do the task. “They are **clear enough** to help us prepare the visitor guide.”","The instructions let us do the task. “They are **clear enough** to help us restore the old portrait.”"],"skill":"form","id":"degree-comparison-foundation-1","domain":"comparison","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"readingVersion":"core-2026-09-v3"},{"title":"Enough has two positions","explanation":"Enough normally follows an adjective or adverb but precedes a noun. It means the required amount or degree has been reached. A following infinitive can explain the purpose.","pattern":"**clear enough** / **enough time**","commonMistakes":["Enough clear and time enough are not the neutral patterns practised here, though literary placements may differ."],"examples":["“We have **enough time** to prepare the visitor guide before lunch.”","“We have **enough time** to restore the old portrait before lunch.”"],"skill":"meaning","id":"degree-comparison-foundation-2","domain":"comparison","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"readingVersion":"core-2026-09-v3"},{"title":"So and such","explanation":"So usually modifies an adjective or adverb. Such modifies a noun phrase, with a/an before a singular count noun. So also combines with much, many, little and few to express quantity.","pattern":"**so useful** / **such a useful guide** / **so many guides**","commonMistakes":["Such useful a guide puts the article in the wrong position for this ordinary pattern."],"examples":["“It is **such a** useful task to prepare the visitor guide.”","“It is **such a** useful task to restore the old portrait.”"],"skill":"contrast","id":"degree-comparison-foundation-3","domain":"comparison","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"readingVersion":"core-2026-09-v3"},{"title":"Modify comparisons and adjective strength","explanation":"Much, far and a little can modify a comparative; very does not normally do so directly. Extreme adjectives often take absolutely rather than very. Ordinary adjectives can take very or quite. The acceptable combinations are partly lexical and depend on the adjective’s sense.","pattern":"**much easier** / **a little easier** / **absolutely exhausted**","commonMistakes":["Very easier is not the ordinary comparative pattern. Some adjectives have both gradable and non-gradable senses."],"examples":["Choose the degree modifier that fits: “It is **much** easier to prepare the visitor guide with help.”","Choose the degree modifier that fits: “It is **much** easier to restore the old portrait with help.”"],"skill":"application","id":"degree-comparison-foundation-4","domain":"comparison","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"readingVersion":"core-2026-09-v3"},{"domain":"comparison","id":"gradable-nongradable","title":"Gradable adjectives, extremes and intensifiers","explanation":"Gradable adjectives allow degrees, such as fairly cold or very cold. Some adjectives express an extreme or a category and typically combine with different intensifiers, such as absolutely exhausted or completely wrong. Real usage can extend or reinterpret these meanings. Treat the combinations as meaning-sensitive preferences rather than an absolute ban on creativity.","pattern":"**very tired** / **absolutely exhausted**","examples":["The answer is **completely wrong**.","The room was **rather small** but **quite comfortable**."],"commonMistakes":["Quite can mean fairly or completely depending on the adjective, dialect and stress. Learn it in a complete expression."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"comparison","id":"progressive-proportional-comparison","title":"More and more, the more…the more and proportions","explanation":"A repeated comparative describes a developing change. Paired the + comparative clauses link two changing quantities or degrees. Multipliers and fractions compare amounts or dimensions using expressions such as twice as much or half as long. Ensure the construction matches whether the noun is countable or non-count.","pattern":"**The more** you practise, **the easier** it becomes.","examples":["It is getting **colder and colder**.","This route is **twice as long as** the other."],"commonMistakes":["Twice longer than can be interpreted inconsistently. Twice as long as is clearer when the intended ratio is two to one."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"comparison","id":"too-enough-result-infinitives","title":"Too and enough with result infinitives","explanation":"Too marks an excessive degree relative to a goal; enough marks sufficiency. Both can introduce an infinitive explaining the relevant possibility. A for-phrase can identify the infinitive’s subject. In some adjective constructions, the understood object of the infinitive is the main-clause subject.","pattern":"The box is **too heavy for me to lift**.","examples":["She is **old enough to travel alone**.","The instructions are **clear enough to follow**."],"commonMistakes":["Do not add an unnecessary object pronoun: This box is too heavy to lift, not too heavy to lift it, in the ordinary linked-object construction."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["The soup is **too hot to drink**.","**clear enough** / **enough time**","**so useful** / **such a useful guide** / **so many guides**","**much easier** / **a little easier** / **absolutely exhausted**"],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["contrast-concession"],"readingReferenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='degree-comparison'
